from typing import List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.test_models.cloud.common import (enter_test_dedicated_state,
                                                                           exit_test_dedicated_state,
                                                                           cleanup_after_test_dedicated_state)


def general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_performance_prach(testing_env: TestingEnv,
                                                                                           cells_names: List[str],
                                                                                           interval: float,
                                                                                           beam_pattern_id: List[int],
                                                                                           reception_slot: int,
                                                                                           expectation_slot: int,
                                                                                           preamble_index: int,
                                                                                           accepted_timing_error: int,
                                                                                           constant_offset: int,
                                                                                           delay_pattern_duration: int,
                                                                                           ru_mode: str,
                                                                                           pfa_target: str,
                                                                                           prach_config_index: int,
                                                                                           prach_root_sequence_index: int,
                                                                                           prach_sequence_type: str,
                                                                                           zero_correlation_zone_config: int,
                                                                                           start_timeout: int = 90,
                                                                                           stop_timeout: int = 90):
    """
    Based on:
    QC Test ID: 203673
    QC Test Name: [2.0] CB010411_L_Operability_CB007120_B_Entering_Test_Dedicated_State_and_run_NR_Performance_PRACH_Via_Web

    Should report to:
    QC Test ID: 70676
    QC Test Name: General_SiSo_Auto_Cloud_Entering_Test_Dedicated_State_And_Running_NR_Performance_PRACH

    :param testing_env: testing environment prepared for this test case
    :param cells_names: names of cells for which NR Performance PRACH test (with same set of parameters) should be run;
                        can be taken from "NRCELL ID" field of cell details in DU WebEM;
                        i.e. ['NRCELL-1', 'NRCELL-3']
    :param interval: reporting time interval to be set before starting NR Performance PRACH test; from <0.1, 3600> range
    :param beam_pattern_id: beam pattern ID to be set before starting NR Performance PRACH test; i.e. [1, 1, 1, 1]
    :param reception_slot: reception slot bit pattern to be set before starting NR Performance PRACH test; from <0, 1023> range
    :param expectation_slot: expectation slot bit pattern to be set before starting NR Performance PRACH test; from <0, 1023> range
    :param preamble_index: preamble index to be set before starting NR Performance PRACH test; from <0, 63> range
    :param accepted_timing_error: accepted timing error to be set before starting NR Performance PRACH test; from <0, 999999> range
    :param constant_offset: constant offset to be set before starting NR Performance PRACH test; from <0, 999999> range
    :param delay_pattern_duration: delay pattern duration to be set before starting NR Performance PRACH test; from <0, 1000> range
    :param ru_mode: RU mode to be set before starting NR Performance PRACH test; one of the following: 'NR_Only', 'MSR', 'Customize_1'
    :param pfa_target: probability false alarm target to be set before starting NR Performance PRACH test;
                       one of the following: 'P_None', 'P_01', 'P_001', 'P_0005', 'P_0001', 'P_005', 'P_05', 'P_10'
    :param prach_config_index: PRACH configuration index to be set before starting NR Performance PRACH test; from <0, 255> range
    :param prach_root_sequence_index: PRACH root sequence index to be set before starting NR Performance PRACH test; from <0, 837> range
    :param prach_sequence_type: PRACH sequence type to be set before starting NR Performance PRACH test;
                                one of the following: 'Unrestricted', 'RestrictedTypeA'
    :param zero_correlation_zone_config: zero correlation zone configuration to be set before starting NR Performance PRACH test; from <0, 15> range
    :param start_timeout: timeout (in seconds) for starting NR Performance PRACH test; defaults to 90
    :param stop_timeout: timeout (in seconds) for stopping NR Performance PRACH test; defaults to 90
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.cells.check_if_names_exist(names=cells_names)

    for du in bts.dus:
        enter_test_dedicated_state(du)

        for cell_name in cells_names:
            try:
                _start_nr_performance_prach_test(du,
                                                 cell_name,
                                                 interval,
                                                 beam_pattern_id,
                                                 reception_slot,
                                                 expectation_slot,
                                                 preamble_index,
                                                 accepted_timing_error,
                                                 constant_offset,
                                                 delay_pattern_duration,
                                                 ru_mode,
                                                 pfa_target,
                                                 prach_config_index,
                                                 prach_root_sequence_index,
                                                 prach_sequence_type,
                                                 zero_correlation_zone_config,
                                                 start_timeout)
                _stop_nr_performance_prach_test(du,
                                                cell_name,
                                                stop_timeout)
            except ResultError as exc:
                errors.add_from_exception(exc)

        exit_test_dedicated_state(du)

    errors.check()


def teardown_for_general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_performance_prach(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    for du in bts.dus:
        cleanup_after_test_dedicated_state(du, errors)


def _start_nr_performance_prach_test(du,
                                     cell_name,
                                     interval,
                                     beam_pattern_id,
                                     reception_slot,
                                     expectation_slot,
                                     preamble_index,
                                     accepted_timing_error,
                                     constant_offset,
                                     delay_pattern_duration,
                                     ru_mode,
                                     pfa_target,
                                     prach_config_index,
                                     prach_root_sequence_index,
                                     prach_sequence_type,
                                     zero_correlation_zone_config,
                                     timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.start_nr_performance_prach_test(cell=cell,
                                                          interval=interval,
                                                          beam_pattern_id=beam_pattern_id,
                                                          reception_slot=reception_slot,
                                                          expectation_slot=expectation_slot,
                                                          preamble_index=preamble_index,
                                                          accepted_timing_error=accepted_timing_error,
                                                          constant_offset=constant_offset,
                                                          delay_pattern_duration=delay_pattern_duration,
                                                          ru_mode=ru_mode,
                                                          pfa_target=pfa_target,
                                                          prach_config_index=prach_config_index,
                                                          prach_root_sequence_index=prach_root_sequence_index,
                                                          prach_sequence_type=prach_sequence_type,
                                                          zero_correlation_zone_config=zero_correlation_zone_config,
                                                          timeout=timeout)


def _stop_nr_performance_prach_test(du, cell_name, timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.stop_nr_performance_test(cell=cell,
                                                   timeout=timeout)
